import { NextResponse } from "next/server";

import { HEADERS, MEDIA_TYPES } from "@/constants/session";

// ProblemDetails response generated by the BFF itself (not the backend).
export function problemResponse(
  status: number,
  code: string,
  headers: Record<string, string> = {},
): NextResponse {
  return NextResponse.json(
    { status, code },
    {
      status,
      headers: { [HEADERS.contentType]: MEDIA_TYPES.problem, ...headers },
    },
  );
}
